const e=JSON.parse('[{"id":"upsc-2018-prelims-csat-a-001","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":1,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the following three dimensional figure :\\n\\nHow many triangles does the above figure have?","options":{"a":"18","b":"20","c":"22","d":"24"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":3,"blocks":[{"type":"paragraph","text":"Consider the following three dimensional figure :"},{"type":"paragraph","text":"How many triangles does the above figure have?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The solid is an icosahedron, which has 20 triangular faces. Hidden edges are dashed; count triangles on the back as well as the front.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-1.png","sourceImageAlt":"Three-dimensional polyhedron with solid visible edges and dashed hidden edges."},{"id":"upsc-2018-prelims-csat-a-002","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":2,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the following sum:\\n• + 1• + 2• + •3 + •1 = 21• In the above sum, • stands for","options":{"a":"4","b":"5","c":"6","d":"8"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":3,"blocks":[{"type":"paragraph","text":"Consider the following sum:\\n• + 1• + 2• + •3 + •1 = 21• In the above sum, • stands for"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Let the dot be d. The sum is d+(10+d)+(20+d)+(10d+3)+(10d+1)=23d+34. Equating it to 210+d gives d=8.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-003","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":3,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the following pattern of numbers:\\n\\n8 | 10 | 15 | 13\\n6 | 5 | 7 | 4\\n4 | 6 | 8 | 8\\n6 | 11 | 16 | ?\\n\\nWhat is the number at ? in the above pattern?","options":{"a":"17","b":"19","c":"21","d":"23"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":3,"blocks":[{"type":"paragraph","text":"Consider the following pattern of numbers:"},{"type":"table","headers":["Column 1","Column 2","Column 3","Column 4"],"rows":[["8","10","15","13"],["6","5","7","4"],["4","6","8","8"],["6","11","16","?"]]},{"type":"paragraph","text":"What is the number at ? in the above pattern?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Each bottom entry equals top minus middle plus third: 8−6+4=6, 10−5+6=11, 15−7+8=16. The last is 13−4+8=17.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-004","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":4,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"How many diagonals can be drawn by joining the vertices of an octagon?","options":{"a":"20","b":"24","c":"28","d":"64"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":3,"blocks":[{"type":"paragraph","text":"How many diagonals can be drawn by joining the vertices of an octagon?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"An n-sided polygon has n(n−3)/2 diagonals. For an octagon this is 8×5/2=20.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-005","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":5,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"The figure drawn below gives the velocity graphs of two vehicles A and B. The straight line OKP represents the velocity of vehicle A at any instant, whereas the horizontal straight line CKD represents the velocity of vehicle B at any instant. In the figure, D is the point where perpendicular from P meets the horizontal line CKD such that PD =1/2LD:\\n\\nWhat is the ratio between the distances covered by vehicles A and B in the time interval OL?","options":{"a":"1 : 2","b":"2 : 3","c":"3 : 4","d":"1 : 1"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":3,"blocks":[{"type":"paragraph","text":"The figure drawn below gives the velocity graphs of two vehicles A and B. The straight line OKP represents the velocity of vehicle A at any instant, whereas the horizontal straight line CKD represents the velocity of vehicle B at any instant. In the figure, D is the point where perpendicular from P meets the horizontal line CKD such that PD =1/2LD:"},{"type":"paragraph","text":"What is the ratio between the distances covered by vehicles A and B in the time interval OL?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Distance is the area under a velocity-time graph. Let LD=h; then LP=LD+DP=1.5h. A covers half of OL×1.5h, while B covers OL×h. Their ratio is 3:4.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-5.png","sourceImageAlt":"Velocity against time: vehicle A follows line OKP; vehicle B follows horizontal CKD. PD is half LD."},{"id":"upsc-2018-prelims-csat-a-006","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":6,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A train 200 metres long is moving at the rate of 40 kmph. In how many seconds will it cross a man standing near the railway line?","options":{"a":"12","b":"15","c":"16","d":"18"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":3,"blocks":[{"type":"paragraph","text":"A train 200 metres long is moving at the rate of 40 kmph. In how many seconds will it cross a man standing near the railway line?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"40 km/h=100/9 m/s. Time to pass the stationary man is 200÷(100/9)=18 seconds.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-007","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":7,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is the most logical and rational inference that can be made from the above passage?","options":{"a":"Prosperity of agriculture sector is of critical importance to India.","b":"Indian economy greatly depends on its agriculture.","c":"India should take strict measures to control its rapid population growth.","d":"India’s farming communities should switch over to other occupations to improve their economic conditions."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=5","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":5,"blocks":[{"type":"passage","text":"Global population was around 1.6 billion in 1900—today it is around 7.2 billion and growing. Recent estimates on population growth predict a global population of 9.6 billion in 2050 and 10.9 billion in 2100. Unlike Europe and North America, where only three to four per cent of population is engaged in agriculture, around 47 per cent of India’s population is dependent upon agriculture. Even if India continues to do well in the service sector and the manufacturing sector picks up, it is expected that around 2030 when India overtakes China as the world’s most populous country, nearly 42 per cent of India’s population will still be predominantly dependent on agriculture."},{"type":"paragraph","text":"Which of the following is the most logical and rational inference that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"A very large share of India’s population is expected to remain dependent on farming. Its prosperity is therefore critical to the country.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-008","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":8,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is the most logical corollary to the above passage?","options":{"a":"With more options for food come more risks.","b":"Food processing is the source of all foodborne illnesses.","c":"We should depend on locally produced food only.","d":"Globalization of food production should be curtailed."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=5","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":5,"blocks":[{"type":"passage","text":"Many pathogens that cause foodborne illnesses are unknown. Food contamination can occur at any stage from farm to plate. Since most cases of food poisoning go unreported, the true extent of global foodborne illnesses is unknown.\\nImprovements in international monitoring have led to greater public awareness, yet the rapid globalization of food production increases consumers’ vulnerability by making food harder to regulate and trace. “We have the world on our plates”, says an official of WHO."},{"type":"paragraph","text":"Which of the following is the most logical corollary to the above passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Global food sourcing adds opportunities for contamination and makes tracing harder. Greater food choice comes with additional risks; the passage does not call for ending globalization.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-009","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":9,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is the most logical and rational inference that can be made from the above passage?","options":{"a":"It is the faith and not science that can finally solve all the problems of mankind.","b":"Science and faith can be mutually complementary if their proper domains are understood.","c":"There are some very fundamental questions which cannot be answered by either science or faith.","d":"In today’s culture, scientific views are given more importance than spiritual views."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"I am a scientist, privileged to be somebody who tries to understand nature using the tools of science. But it is also clear that there are some really important questions that science cannot really answer, such as : Why is there something instead of nothing? Why are we here? In those domains, I have found that faith provides a better path to answers. I find it oddly anachronistic that in today’s culture there seems to be a widespread presumption that scientific and spiritual views are incompatible."},{"type":"paragraph","text":"Which of the following is the most logical and rational inference that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The scientist uses science to understand nature and faith for questions outside science’s reach. The two can complement one another within their proper domains.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-010","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":10,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The author wants India to rid herself of certain past bonds because","options":{"a":"he is not able to see the relevance of the past","b":"there is not much to be proud of","c":"he is not interested in the history of India","d":"they obstruct her physical and spiritual growth"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"Though I have discarded much of past tradition and custom, and am anxious that India should rid herself of all shackles that bind and contain her and divide her people, and suppress vast numbers of them, and prevent the free development of the body and the spirit; though I seek all this, yet I do not wish to cut myself off from that past completely. I am proud of that great inheritance that has been and is, ours and I am conscious that I too, like all of us, am a link in that unbroken chain which goes back to the dawn of history in the immemorial past of India."},{"type":"paragraph","text":"The author wants India to rid herself of certain past bonds because"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The author objects to traditions that divide people and suppress free development of body and spirit, while still valuing India’s inheritance.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-011","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":11,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"By how much (measured in thousands of tons) did the import of sheet steel exceed the import of coil steel in the first three months of the year?","options":{"a":"11","b":"15","c":"19","d":"23"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"The graph shows imports of three different types of steel over a period of six months of a year. The figures in brackets indicate the average cost per ton over the six-month period."},{"type":"paragraph","text":"By how much (measured in thousands of tons) did the import of sheet steel exceed the import of coil steel in the first three months of the year?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"For January to March sheet steel totals 40+37+36=113 and coil steel 30+31+33=94, in thousands of tons. The difference is 19.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-11.png","sourceImageAlt":"Bar chart of coil, sheet and scrap steel imports from January to June, with costs per ton shown below."},{"id":"upsc-2018-prelims-csat-a-012","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":12,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"What was the approximate total value (in $) of sheet steel imported over the six months period?","options":{"a":"45,555","b":"50,555","c":"55,550","d":"65,750"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"The graph shows imports of three different types of steel over a period of six months of a year. The figures in brackets indicate the average cost per ton over the six-month period."},{"type":"paragraph","text":"What was the approximate total value (in $) of sheet steel imported over the six months period?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Sheet steel totals approximately 217 graph units over six months. Multiplying by $256 per ton gives about 55,552 in the question’s scaled units, closest to 55,550.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-11.png","sourceImageAlt":"Bar chart of coil, sheet and scrap steel imports from January to June, with costs per ton shown below."},{"id":"upsc-2018-prelims-csat-a-013","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":13,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Data interpretation","question":"What was the approximate ratio of sheet steel and scrap steel imports in the first three months of the year?","options":{"a":"1 : 1","b":"1.2 : 1","c":"1.4 : 1","d":"1.6 : 1"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"The graph shows imports of three different types of steel over a period of six months of a year. The figures in brackets indicate the average cost per ton over the six-month period."},{"type":"paragraph","text":"What was the approximate ratio of sheet steel and scrap steel imports in the first three months of the year?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"For the first three months sheet steel totals 113 and scrap steel 32+34+32=98. The ratio is about 1.15:1, closest to 1.2:1.","concept":"Data interpretation","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-11.png","sourceImageAlt":"Bar chart of coil, sheet and scrap steel imports from January to June, with costs per ton shown below."},{"id":"upsc-2018-prelims-csat-a-014","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":14,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"What is the symbol on the face opposite to that containing a single dot?","options":{"a":"Four dots","b":"Three dots","c":"Two dots","d":"Cross"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=9","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":9,"blocks":[{"type":"passage","text":"Rotated positions of a single solid are shown. The various faces of the solid are marked with different symbols like dots, cross and line."},{"type":"paragraph","text":"What is the symbol on the face opposite to that containing a single dot?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Comparing the cube rotations pairs the single-dot face with the three-dot face on opposite sides.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-14.png","sourceImageAlt":"Four rotations of one cube, with faces marked by one to four dots, a cross and a line."},{"id":"upsc-2018-prelims-csat-a-015","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":15,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"What is the symbol on the face opposite to that containing two dots?","options":{"a":"Single dot","b":"Three dots","c":"Four dots","d":"Line"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=9","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":9,"blocks":[{"type":"passage","text":"Rotated positions of a single solid are shown. The various faces of the solid are marked with different symbols like dots, cross and line."},{"type":"paragraph","text":"What is the symbol on the face opposite to that containing two dots?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The four-dot face is opposite the two-dot face when the rotations are aligned consistently.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-14.png","sourceImageAlt":"Four rotations of one cube, with faces marked by one to four dots, a cross and a line."},{"id":"upsc-2018-prelims-csat-a-016","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":16,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"What is the symbol on the face opposite to that containing the cross?","options":{"a":"Single dot","b":"Two dots","c":"Line","d":"Four dots"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=9","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":9,"blocks":[{"type":"passage","text":"Rotated positions of a single solid are shown. The various faces of the solid are marked with different symbols like dots, cross and line."},{"type":"paragraph","text":"What is the symbol on the face opposite to that containing the cross?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The cross and the line form the remaining pair of opposite faces.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]},"sourceImage":"./paper-figures/cse-2018-csat-14.png","sourceImageAlt":"Four rotations of one cube, with faces marked by one to four dots, a cross and a line."},{"id":"upsc-2018-prelims-csat-a-017","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":17,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"According to the passage, which of the following is/are of paramount importance under the Right to Education?\\n\\n1. Sending of children to school by all parents\\n2. Provision of adequate physical infrastructure in schools\\n3. Curricular reforms for developing child-friendly learning system\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"1 and 2 only","c":"3 only","d":"None of the above"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":11,"blocks":[{"type":"passage","text":"It is no longer enough for us to talk about providing for universal access to education. Making available schooling facilities is an essential prerequisite, but is insufficient to ensure that all children attend school and participate in the learning process. The school may be there, but children may not attend or they may drop out after a few months. Through school and social mapping, we must address the entire gamut of social, economic, cultural and indeed linguistic and pedagogic issues, factors that prevent children from weaker sections and disadvantaged groups, as also girls, from regularly attending and completing elementary education. The focus must be on the poorest and most vulnerable since these groups are the most disempowered and at the greatest risk of violation or denial of their right to education. The right to education goes beyond free and compulsory education to include quality education for all. Quality is an integral part of the right to education. If the education process lacks quality, children are being denied their right. The Right of Children to Free and Compulsory Education Act lays down that the curriculum should provide for learning through activities, exploration and discovery. This places an obligation on us to change our perception of children as passive receivers of knowledge, and to move beyond the convention of using textbooks as the basis of examinations. The teaching-learning process must become stress-free, and a massive programme for curricular reform should be initiated to provide for a child-friendly learning system, that is more relevant and empowering. Teacher accountability systems and processes must ensure that children are learning, and that their right to learn in a child-friendly environment is not violated.\\nTesting and assessment systems must be reexamined and redesigned to ensure that these do not force children to struggle between school and tuition centres, and bypass childhood."},{"type":"paragraph","text":"According to the passage, which of the following is/are of paramount importance under the Right to Education?"},{"type":"paragraph","text":"1. Sending of children to school by all parents\\n2. Provision of adequate physical infrastructure in schools\\n3. Curricular reforms for developing child-friendly learning system"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage treats physical access as insufficient and stresses a child-friendly curriculum. Of the listed items, curricular reform is the accepted priority.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-018","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":18,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, the following assumptions have been made :\\n\\n1. The Right to Education guarantees teachers’ accountability for the learning process of children.\\n2. The Right to Education guarantees 100% enrolment of children in the schools.\\n3. The Right to Education intends to take full advantage of demographic dividend.\\n\\nWhich of the above assumptions is/ are valid?","options":{"a":"1 only","b":"2 and 3 only","c":"3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":11,"blocks":[{"type":"passage","text":"It is no longer enough for us to talk about providing for universal access to education. Making available schooling facilities is an essential prerequisite, but is insufficient to ensure that all children attend school and participate in the learning process. The school may be there, but children may not attend or they may drop out after a few months. Through school and social mapping, we must address the entire gamut of social, economic, cultural and indeed linguistic and pedagogic issues, factors that prevent children from weaker sections and disadvantaged groups, as also girls, from regularly attending and completing elementary education. The focus must be on the poorest and most vulnerable since these groups are the most disempowered and at the greatest risk of violation or denial of their right to education. The right to education goes beyond free and compulsory education to include quality education for all. Quality is an integral part of the right to education. If the education process lacks quality, children are being denied their right. The Right of Children to Free and Compulsory Education Act lays down that the curriculum should provide for learning through activities, exploration and discovery. This places an obligation on us to change our perception of children as passive receivers of knowledge, and to move beyond the convention of using textbooks as the basis of examinations. The teaching-learning process must become stress-free, and a massive programme for curricular reform should be initiated to provide for a child-friendly learning system, that is more relevant and empowering. Teacher accountability systems and processes must ensure that children are learning, and that their right to learn in a child-friendly environment is not violated.\\nTesting and assessment systems must be reexamined and redesigned to ensure that these do not force children to struggle between school and tuition centres, and bypass childhood."},{"type":"paragraph","text":"With reference to the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. The Right to Education guarantees teachers’ accountability for the learning process of children.\\n2. The Right to Education guarantees 100% enrolment of children in the schools.\\n3. The Right to Education intends to take full advantage of demographic dividend."},{"type":"paragraph","text":"Which of the above assumptions is/ are valid?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Teacher accountability for children’s learning is explicitly discussed. Guaranteed full enrolment and use of a demographic dividend are not established; only assumption 1 is valid.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-019","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":19,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"According to the passage, which one of the following is critical in bringing quality in education?","options":{"a":"Ensuring regular attendance of children as well as teachers in school","b":"Giving pecuniary benefits to teachers to motivate them","c":"Understanding the socio cultural background of children","d":"Inculcating learning through activities and discovery"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":11,"blocks":[{"type":"passage","text":"It is no longer enough for us to talk about providing for universal access to education. Making available schooling facilities is an essential prerequisite, but is insufficient to ensure that all children attend school and participate in the learning process. The school may be there, but children may not attend or they may drop out after a few months. Through school and social mapping, we must address the entire gamut of social, economic, cultural and indeed linguistic and pedagogic issues, factors that prevent children from weaker sections and disadvantaged groups, as also girls, from regularly attending and completing elementary education. The focus must be on the poorest and most vulnerable since these groups are the most disempowered and at the greatest risk of violation or denial of their right to education. The right to education goes beyond free and compulsory education to include quality education for all. Quality is an integral part of the right to education. If the education process lacks quality, children are being denied their right. The Right of Children to Free and Compulsory Education Act lays down that the curriculum should provide for learning through activities, exploration and discovery. This places an obligation on us to change our perception of children as passive receivers of knowledge, and to move beyond the convention of using textbooks as the basis of examinations. The teaching-learning process must become stress-free, and a massive programme for curricular reform should be initiated to provide for a child-friendly learning system, that is more relevant and empowering. Teacher accountability systems and processes must ensure that children are learning, and that their right to learn in a child-friendly environment is not violated.\\nTesting and assessment systems must be reexamined and redesigned to ensure that these do not force children to struggle between school and tuition centres, and bypass childhood."},{"type":"paragraph","text":"According to the passage, which one of the following is critical in bringing quality in education?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage specifies learning through activities, exploration and discovery as the means of quality education.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-020","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":20,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is the essential message in this passage?","options":{"a":"The Right to Education now is a Fundamental Right.","b":"The Right to Education enables the children of poor and weaker sections of the society to attend schools.","c":"The Right to Free and Compulsory Education should include quality education for all.","d":"The Government as well as parents should ensure that all children attend schools."},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":11,"blocks":[{"type":"passage","text":"It is no longer enough for us to talk about providing for universal access to education. Making available schooling facilities is an essential prerequisite, but is insufficient to ensure that all children attend school and participate in the learning process. The school may be there, but children may not attend or they may drop out after a few months. Through school and social mapping, we must address the entire gamut of social, economic, cultural and indeed linguistic and pedagogic issues, factors that prevent children from weaker sections and disadvantaged groups, as also girls, from regularly attending and completing elementary education. The focus must be on the poorest and most vulnerable since these groups are the most disempowered and at the greatest risk of violation or denial of their right to education. The right to education goes beyond free and compulsory education to include quality education for all. Quality is an integral part of the right to education. If the education process lacks quality, children are being denied their right. The Right of Children to Free and Compulsory Education Act lays down that the curriculum should provide for learning through activities, exploration and discovery. This places an obligation on us to change our perception of children as passive receivers of knowledge, and to move beyond the convention of using textbooks as the basis of examinations. The teaching-learning process must become stress-free, and a massive programme for curricular reform should be initiated to provide for a child-friendly learning system, that is more relevant and empowering. Teacher accountability systems and processes must ensure that children are learning, and that their right to learn in a child-friendly environment is not violated.\\nTesting and assessment systems must be reexamined and redesigned to ensure that these do not force children to struggle between school and tuition centres, and bypass childhood."},{"type":"paragraph","text":"What is the essential message in this passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Its central argument is that the right to education must provide quality, rather than merely free access or compulsory attendance.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-021","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":21,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If LSJXVC is the code for MUMBAI, the code for DELHI is","options":{"a":"CCIDD","b":"CDKGH","c":"CCJFG","d":"CCIFE"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":13,"blocks":[{"type":"paragraph","text":"If LSJXVC is the code for MUMBAI, the code for DELHI is"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Letters move back by 1, 2, 3, 4, 5 and 6 places in MUMBAI→LSJXVC. Applying the first five shifts to DELHI gives CCIDD.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-022","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":22,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If RAMON is written as 12345 and DINESH as 675849, then HAMAM will be written as","options":{"a":"92233","b":"92323","c":"93322","d":"93232"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":13,"blocks":[{"type":"paragraph","text":"If RAMON is written as 12345 and DINESH as 675849, then HAMAM will be written as"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The substitution assigns H=9, A=2 and M=3. HAMAM is therefore 92323.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-023","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":23,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If X is between -3 and -1, and Y is between -1 and 1, then X² - Y² is in between which of the following?","options":{"a":"-9 and 1","b":"-9 and -1","c":"0 and 8","d":"0 and 9"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":13,"blocks":[{"type":"paragraph","text":"If X is between -3 and -1, and Y is between -1 and 1, then X² - Y² is in between which of the following?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Since −3<X<−1, 1<X²<9; since −1<Y<1, 0≤Y²<1. Consequently 0<X²−Y²<9.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-024","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":24,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"X and Y are natural numbers other than 1, and Y is greater than X.\\nWhich of the following represents the largest number?","options":{"a":"XY","b":"X / Y","c":"Y / X","d":"(X + Y) /XY"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":13,"blocks":[{"type":"paragraph","text":"X and Y are natural numbers other than 1, and Y is greater than X.\\nWhich of the following represents the largest number?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"X≥2 and Y>X. The product XY exceeds Y/X, X/Y and 1/X+1/Y, so XY is largest.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-025","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":25,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If E sits in his office and faces the corridor, whose office is to his left?","options":{"a":"A","b":"B","c":"C","d":"D"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":13,"blocks":[{"type":"passage","text":"The plan of an office block for six officers A, B, C, D, E and F is as follows : Both B and C occupy offices to the right of the corridor (as one enters the office block) and A occupies on the left of the corridor. E and F occupy offices on opposite sides of the corridor but their offices do not face each other. The offices of C and D face each other. E does not have a corner office. F’s office is further down the corridor than A’s, but on the same side."},{"type":"paragraph","text":"If E sits in his office and faces the corridor, whose office is to his left?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The constraints place C, E, B on the right and D, A, F on the left, ordered from the entrance. Facing the corridor, E has C to his left.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-026","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":26,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Who is/are F’s immediate neighbour/ neighbours?","options":{"a":"A only","b":"A and D","c":"C only","d":"B and C"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":13,"blocks":[{"type":"passage","text":"The plan of an office block for six officers A, B, C, D, E and F is as follows : Both B and C occupy offices to the right of the corridor (as one enters the office block) and A occupies on the left of the corridor. E and F occupy offices on opposite sides of the corridor but their offices do not face each other. The offices of C and D face each other. E does not have a corner office. F’s office is further down the corridor than A’s, but on the same side."},{"type":"paragraph","text":"Who is/are F’s immediate neighbour/ neighbours?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"F occupies an end office on A’s side of the corridor. Its only immediate neighbour is A.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-027","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":27,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"According to the passage, which of the following are the consequences of decline in forest cover?\\n\\n1. Loss of topsoil\\n2. Loss of smaller rivers\\n3. Adverse effect on agricultural production\\n4. Declining of groundwater.\\n\\nSelect the correct answer using the code given below,","options":{"a":"1, 2 and 3 only","b":"2, 3 and 4 only","c":"1 and 4 only","d":"1, 2, 3 and 4"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=15","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":15,"blocks":[{"type":"passage","text":"`Desertification’ is a term used to explain a process of decline in the biological productivity of an ecosystem, leading to total loss of productivity.\\nWhile this phenomenon is often linked to the arid, semi-arid and sub-humid ecosystems, even in the humid tropics, the impact could be most dramatic.\\nImpoverishment of human-impacted terrestrial ecosystems may exhibit itself in a variety of ways : accelerated erosion as in the mountain regions of the country, salinization of land as in the semi-arid and arid ‘green revolution’ areas of the country, e.g., Haryana and western Uttar Pradesh, and site quality decline—a common phenomenon due to general decline in tree cover and monotonous monoculture of rice/wheat across the Indian plains. A major consequence of deforestation is that it relates to adverse alterations in the hydrology and related soil and nutrient losses. The consequences of deforestation invariably arise out of site degradation through erosive losses. Tropical Asia, Africa and South America have the highest levels of erosion. The already high rates for the tropics are increasing at an alarming rate (e.g., through the major river systems— Ganga and Brahmaputra, in the context), due to deforestation and land management practices subsequent to forest clearing. In the mountain context, the declining moisture retention of the mountain soils, drying up of the underground springs and smaller rivers in the Himalayas could be attributed to drastic changes in the forest cover. An indirect consequence is drastic alteration in the upland-lowland interaction, mediated through water. The current concern of the tea planter of Assam has is about the damage to tea plantations due to frequent inundation along the flood-plains of Brahmaputra, and the damage to tea plantation and the consequent loss in tea productivity is due to rising level of the river bottom because of siltation and the changing course of the river system. The ultimate consequences of site desertification are soil degradation, alteration in available water and its quality, and the consequent decline in food, fodder and fuel-wood essential for the economic well-being of rural communities."},{"type":"paragraph","text":"According to the passage, which of the following are the consequences of decline in forest cover?"},{"type":"paragraph","text":"1. Loss of topsoil\\n2. Loss of smaller rivers\\n3. Adverse effect on agricultural production\\n4. Declining of groundwater."},{"type":"paragraph","text":"Select the correct answer using the code given below,"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage associates deforestation with erosion, loss of springs and smaller rivers, reduced farm output and reduced water retention. All four consequences are supported.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-028","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":28,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is/are the correct inference/inferences that can be made from the passage?\\n\\n1. Deforestation can cause changes in the course of rivers.\\n2. Salinization of land takes place due to human activities only.\\n3. Intense monoculture practice in plains is a major reason for desertification in Tropical Asia, Africa and South America.\\n\\nSelect the correct answer using the code given below.","options":{"a":"1 only","b":"1 and 2 only","c":"2 and 3 only","d":"None of the above is a correct inference"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=15","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":15,"blocks":[{"type":"passage","text":"`Desertification’ is a term used to explain a process of decline in the biological productivity of an ecosystem, leading to total loss of productivity.\\nWhile this phenomenon is often linked to the arid, semi-arid and sub-humid ecosystems, even in the humid tropics, the impact could be most dramatic.\\nImpoverishment of human-impacted terrestrial ecosystems may exhibit itself in a variety of ways : accelerated erosion as in the mountain regions of the country, salinization of land as in the semi-arid and arid ‘green revolution’ areas of the country, e.g., Haryana and western Uttar Pradesh, and site quality decline—a common phenomenon due to general decline in tree cover and monotonous monoculture of rice/wheat across the Indian plains. A major consequence of deforestation is that it relates to adverse alterations in the hydrology and related soil and nutrient losses. The consequences of deforestation invariably arise out of site degradation through erosive losses. Tropical Asia, Africa and South America have the highest levels of erosion. The already high rates for the tropics are increasing at an alarming rate (e.g., through the major river systems— Ganga and Brahmaputra, in the context), due to deforestation and land management practices subsequent to forest clearing. In the mountain context, the declining moisture retention of the mountain soils, drying up of the underground springs and smaller rivers in the Himalayas could be attributed to drastic changes in the forest cover. An indirect consequence is drastic alteration in the upland-lowland interaction, mediated through water. The current concern of the tea planter of Assam has is about the damage to tea plantations due to frequent inundation along the flood-plains of Brahmaputra, and the damage to tea plantation and the consequent loss in tea productivity is due to rising level of the river bottom because of siltation and the changing course of the river system. The ultimate consequences of site desertification are soil degradation, alteration in available water and its quality, and the consequent decline in food, fodder and fuel-wood essential for the economic well-being of rural communities."},{"type":"paragraph","text":"Which of the following is/are the correct inference/inferences that can be made from the passage?"},{"type":"paragraph","text":"1. Deforestation can cause changes in the course of rivers.\\n2. Salinization of land takes place due to human activities only.\\n3. Intense monoculture practice in plains is a major reason for desertification in Tropical Asia, Africa and South America."},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Changes in river courses due to siltation are explicitly discussed. “Human activities only” and the generalized claim about monoculture in all three tropical regions are stronger than the passage establishes. Only 1 is accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-029","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":29,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to ‘desertification’, as described in the passage, the following assumptions have been made :\\n\\n1. Desertification is a phenomenon in tropical areas only.\\n2. Deforestation invariably leads to floods and desertification.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=15","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":15,"blocks":[{"type":"passage","text":"`Desertification’ is a term used to explain a process of decline in the biological productivity of an ecosystem, leading to total loss of productivity.\\nWhile this phenomenon is often linked to the arid, semi-arid and sub-humid ecosystems, even in the humid tropics, the impact could be most dramatic.\\nImpoverishment of human-impacted terrestrial ecosystems may exhibit itself in a variety of ways : accelerated erosion as in the mountain regions of the country, salinization of land as in the semi-arid and arid ‘green revolution’ areas of the country, e.g., Haryana and western Uttar Pradesh, and site quality decline—a common phenomenon due to general decline in tree cover and monotonous monoculture of rice/wheat across the Indian plains. A major consequence of deforestation is that it relates to adverse alterations in the hydrology and related soil and nutrient losses. The consequences of deforestation invariably arise out of site degradation through erosive losses. Tropical Asia, Africa and South America have the highest levels of erosion. The already high rates for the tropics are increasing at an alarming rate (e.g., through the major river systems— Ganga and Brahmaputra, in the context), due to deforestation and land management practices subsequent to forest clearing. In the mountain context, the declining moisture retention of the mountain soils, drying up of the underground springs and smaller rivers in the Himalayas could be attributed to drastic changes in the forest cover. An indirect consequence is drastic alteration in the upland-lowland interaction, mediated through water. The current concern of the tea planter of Assam has is about the damage to tea plantations due to frequent inundation along the flood-plains of Brahmaputra, and the damage to tea plantation and the consequent loss in tea productivity is due to rising level of the river bottom because of siltation and the changing course of the river system. The ultimate consequences of site desertification are soil degradation, alteration in available water and its quality, and the consequent decline in food, fodder and fuel-wood essential for the economic well-being of rural communities."},{"type":"paragraph","text":"With reference to ‘desertification’, as described in the passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Desertification is a phenomenon in tropical areas only.\\n2. Deforestation invariably leads to floods and desertification."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage includes non-tropical ecosystems and does not say every deforestation event inevitably causes both floods and desertification. Neither assumption is valid.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-030","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":30,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, which of the following would assist us in coping with the climate change?\\n\\n1. Conservation of natural water sources\\n2. Conservation of wider gene pool\\n3. Existing crop management practices\\n4. Migration corridors\\n\\nSelect the correct answer using the code given below.","options":{"a":"1, 2 and 3 only","b":"1, 2 and 4 only","c":"3 and 4 only","d":"1, 2, 3 and 4"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=17","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":17,"blocks":[{"type":"passage","text":"A diversity of natural assets will be needed to cope with climate change and ensure productive agriculture, forestry, and fisheries. For example, crop varieties are needed that perform well under drought, heat, and enhanced CO2.\\nBut the private sector and farmer-led process of choosing crops favours homogeneity adapted to past or current conditions, not varieties capable of producing consistently high yields in warmer, wetter, or drier conditions.\\nAccelerated breeding programmes are needed to conserve a wider pool of genetic resources of existing crops, breeds, and their wild relatives. Relatively intact ecosystems, such as forested catchments, mangroves, wetlands, can buffer the impacts of climate change. Under a changing climate, these ecosystems are themselves at risk, and management approaches will need to be more proactive and adaptive. Connections between natural areas, such as migration corridors, may be needed to facilitate species movements to keep up with the change in climate."},{"type":"paragraph","text":"With reference to the above passage, which of the following would assist us in coping with the climate change?"},{"type":"paragraph","text":"1. Conservation of natural water sources\\n2. Conservation of wider gene pool\\n3. Existing crop management practices\\n4. Migration corridors"},{"type":"paragraph","text":"Select the correct answer using the code given below."}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Water conservation, a wider gene pool and migration corridors are described as coping measures. Existing crop practices alone are not the suggested adaptation; 1, 2 and 4 are accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-031","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":31,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, the following assumptions have been made :\\n\\n1. Diversification of livelihoods acts as a coping strategy for climate change.\\n\\n2. Adoption of monocropping practice leads to the extinction of plant varieties and their wild relatives. Which of the above assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=17","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":17,"blocks":[{"type":"passage","text":"A diversity of natural assets will be needed to cope with climate change and ensure productive agriculture, forestry, and fisheries. For example, crop varieties are needed that perform well under drought, heat, and enhanced CO2.\\nBut the private sector and farmer-led process of choosing crops favours homogeneity adapted to past or current conditions, not varieties capable of producing consistently high yields in warmer, wetter, or drier conditions.\\nAccelerated breeding programmes are needed to conserve a wider pool of genetic resources of existing crops, breeds, and their wild relatives. Relatively intact ecosystems, such as forested catchments, mangroves, wetlands, can buffer the impacts of climate change. Under a changing climate, these ecosystems are themselves at risk, and management approaches will need to be more proactive and adaptive. Connections between natural areas, such as migration corridors, may be needed to facilitate species movements to keep up with the change in climate."},{"type":"paragraph","text":"With reference to the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Diversification of livelihoods acts as a coping strategy for climate change."},{"type":"paragraph","text":"2. Adoption of monocropping practice leads to the extinction of plant varieties and their wild relatives. Which of the above assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"UPSC accepts both assumptions. The passage’s emphasis on diverse natural assets supports livelihood diversification as adaptation, while conserving a wider gene pool counters the loss of varieties and wild relatives associated with homogeneity and monocropping.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-032","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":32,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is the most crucial and logical inference that can be made from the above passage?","options":{"a":"The Earth can meet only the basic needs of humans for food, clothing and shelter.","b":"The only way to meet environmental challenge is to limit human population.","c":"Reducing our consumerism is very much in our own interest.","d":"Knowledge of biological systems can only help us save this planet."},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=17","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":17,"blocks":[{"type":"passage","text":"Today, the top environmental challenge is a combination of people and their aspirations. If the aspirations are more like the frugal ones we had after the Second World War, a lot more is possible than if we view the planet as a giant shopping mall. We need to get beyond the fascination with glitter and understand that the planet works as a biological system."},{"type":"paragraph","text":"Which of the following is the most crucial and logical inference that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage describes limits on ecosystems and the damage from consuming beyond them. Reducing consumerism follows more directly than the absolute alternatives.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-033","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":33,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The author of the passage holds the view that","options":{"a":"leadership can be taught through war experience only","b":"leadership can be acquired as well as taught","c":"the results of training show that more people acquire leadership than are expected","d":"despite rigorous instruction, very few leaders are produced"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":19,"blocks":[{"type":"passage","text":"Some people believe that leadership is a quality which you have at birth or not at all. This theory is false, for the art of leadership can be acquired and can indeed be taught. This discovery is made in time of war and the results achieved can surprise even the instructors. Faced with the alternatives of going left or right, every soldier soon grasps that a prompt decision either way is better than an endless discussion. A firm choice of direction has an even chance of being right while to do nothing will be almost certainly wrong."},{"type":"paragraph","text":"The author of the passage holds the view that"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The passage explicitly rejects the idea that leadership is entirely inborn and says its art can be acquired and taught. The wartime example illustrates this learning.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-034","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":34,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A number consists of three digits of which the middle one is zero and their sum is 4. If the number formed by interchanging the first and last digits is greater than the number itself by 198, the difference between the first and last digits is","options":{"a":"1","b":"2","c":"3","d":"4"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":19,"blocks":[{"type":"paragraph","text":"A number consists of three digits of which the middle one is zero and their sum is 4. If the number formed by interchanging the first and last digits is greater than the number itself by 198, the difference between the first and last digits is"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"If the first and last digits are a and c, reversing the number changes it by 99(c−a)=198. Their difference is 2.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-035","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":35,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A solid cube of 3 cm side, painted on all its faces, is cut up into small cubes of 1 cm side. How many of the small cubes will have exactly two painted faces?","options":{"a":"12","b":"8","c":"6","d":"4"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":19,"blocks":[{"type":"paragraph","text":"A solid cube of 3 cm side, painted on all its faces, is cut up into small cubes of 1 cm side. How many of the small cubes will have exactly two painted faces?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Exactly two painted faces occur on edge cubes that are not corners. There are 12 edges, each with 3−2=1 such cube, giving 12.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-036","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":36,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"While writing all the numbers from 700 to 1000, how many numbers occur in which the digit at hundred’s place is greater than the digit at ten’s place, and the digit at ten’s place is greater than the digit at unit’s place?","options":{"a":"61","b":"64","c":"85","d":"91"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":19,"blocks":[{"type":"paragraph","text":"While writing all the numbers from 700 to 1000, how many numbers occur in which the digit at hundred’s place is greater than the digit at ten’s place, and the digit at ten’s place is greater than the digit at unit’s place?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"For hundreds digits 7, 8 and 9, choose a descending pair of lower digits from 0–6, 0–7 and 0–8 respectively: C(7,2)+C(8,2)+C(9,2)=21+28+36=85.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-037","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":37,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If Pen < Pencil, Pencil < Book and Book > Cap, then which one of the following is always true?","options":{"a":"Pen > Cap","b":"Pen < Book","c":"Pencil = Cap","d":"Pencil > Cap"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":19,"blocks":[{"type":"paragraph","text":"If Pen < Pencil, Pencil < Book and Book > Cap, then which one of the following is always true?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Transitivity gives Pen<Pencil<Book, so Pen<Book always. No comparison between Pen or Pencil and Cap is fixed.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-038","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":38,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A bookseller sold ‘a’ number of Geography textbooks at the rate of ₹x per book, ‘a + 2’ number of History textbooks at the rate of ₹(x + 2) per book and ‘a − 2’ number of Mathematics textbooks at the rate of ₹(x − 2) per book. What is his total sale in ₹?","options":{"a":"3x + 3a","b":"3ax + 8","c":"9ax","d":"x³a³"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"A bookseller sold ‘a’ number of Geography textbooks at the rate of ₹x per book, ‘a + 2’ number of History textbooks at the rate of ₹(x + 2) per book and ‘a − 2’ number of Mathematics textbooks at the rate of ₹(x − 2) per book. What is his total sale in ₹?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"The total is ax+(a+2)(x+2)+(a−2)(x−2)=3ax+8.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-039","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":39,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A bag contains 15 red balls and 20 black balls. Each ball is numbered either 1 or 2 or 3. 20% of the red balls are numbered 1 and 40% of them are numbered 3. Similarly, among the black balls, 45% are numbered 2 and 30% are numbered 3. A boy picks a ball at random. He wins if the ball is red and numbered 3 or if it is black and numbered 1 or 2. What are the chances of his winning?","options":{"a":"1/2","b":"4/7","c":"5/9","d":"12/13"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"A bag contains 15 red balls and 20 black balls. Each ball is numbered either 1 or 2 or 3. 20% of the red balls are numbered 1 and 40% of them are numbered 3. Similarly, among the black balls, 45% are numbered 2 and 30% are numbered 3. A boy picks a ball at random. He wins if the ball is red and numbered 3 or if it is black and numbered 1 or 2. What are the chances of his winning?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"Winning balls are 6 red balls numbered 3 and 20−6=14 black balls numbered 1 or 2. The probability is 20/35=4/7.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}},{"id":"upsc-2018-prelims-csat-a-040","year":2018,"stage":"CSAT","paper":"CSAT Paper II","number":40,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Two persons, A and B are running on a circular track. At the start, B is ahead of A and their positions make an angle of 30° at the centre of the circle. When A reaches the point diametrically opposite to his starting point, he meets B. What is the ratio of speeds of A and B, if they are running with uniform speeds?","options":{"a":"6 : 5","b":"4 : 3","c":"6 : 1","d":"4 : 2"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/csat-2018-question-paper.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"Two persons, A and B are running on a circular track. At the start, B is ahead of A and their positions make an angle of 30° at the centre of the circle. When A reaches the point diametrically opposite to his starting point, he meets B. What is the ratio of speeds of A and B, if they are running with uniform speeds?"}],"sourceTitle":"UPSC CSE 2018 CSAT Paper II · Series A","explanation":{"justification":"A travels through 180° and B through 180°−30°=150° in the same time. Their speed ratio is 180:150=6:5.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2018 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-CSAT.pdf#page=1"}]}}]');export{e as p};
